import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant Users API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Users API | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-users"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Users API | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-users"}]]},"headers":[],"relativePath":"api/tenant-v1-users.md","filePath":"api/tenant-v1-users.md","lastUpdated":1786141446000}'),i={name:"api/tenant-v1-users.md"};function n(r,e,d,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="tenant-users-api" tabindex="-1">Tenant Users API <a class="header-anchor" href="#tenant-users-api" aria-label="Permalink to &quot;Tenant Users API&quot;">​</a></h1><p>Workspace user administration under <code>/api/tenant/v1/users</code> (Sanctum <code>tenant-api</code>, tenancy middleware, permission gates).</p><h2 id="employee-link-field" tabindex="-1">Employee link field <a class="header-anchor" href="#employee-link-field" aria-label="Permalink to &quot;Employee link field&quot;">​</a></h2><p>Returned on list/show:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>employee_id</code></td><td>integer | null</td><td>Id of the linked Employees directory row when one exists; otherwise <code>null</code>.</td></tr></tbody></table><h2 id="create-employee-from-user" tabindex="-1">Create employee from user <a class="header-anchor" href="#create-employee-from-user" aria-label="Permalink to &quot;Create employee from user&quot;">​</a></h2><h3 id="post-users-user-create-employee" tabindex="-1"><code>POST /users/{user}/create-employee</code> <a class="header-anchor" href="#post-users-user-create-employee" aria-label="Permalink to &quot;\`POST /users/{user}/create-employee\`&quot;">​</a></h3><p>Creates a linked Employees directory record for a user that does not already have one (retrofit after installing the Employees module).</p><table tabindex="0"><thead><tr><th>Middleware</th><th>Value</th></tr></thead><tbody><tr><td>Module</td><td><code>module:employees</code></td></tr><tr><td>Permission</td><td><code>can:employees.create</code></td></tr><tr><td>Policy</td><td>Actor must be able to <code>view</code> the user</td></tr></tbody></table><p>Defaults: next <code>EMP-####</code> number, name split from <code>user.name</code>, <code>email</code> from the user, hire date = today in the workspace timezone, <code>employment_type = full_time</code>, <code>status = active</code> (or <code>inactive</code> if the user is suspended). Concurrent calls are serialized with a user-row lock. Soft-deleted employees keep historical <code>user_id</code> but clear <code>active_user_id</code>, so re-provision is allowed.</p><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>201</code></td><td>Employee created (body uses Employee resource)</td></tr><tr><td><code>404</code></td><td>User soft-deleted</td></tr><tr><td><code>403</code></td><td>Module not installed or missing <code>employees.create</code></td></tr><tr><td><code>422</code></td><td>User already has an active linked employee</td></tr></tbody></table><p>Also: create user accepts optional <code>create_employee</code> (boolean, default <code>true</code> when Employees is installed).</p><h2 id="crm-preference-fields" tabindex="-1">CRM preference fields <a class="header-anchor" href="#crm-preference-fields" aria-label="Permalink to &quot;CRM preference fields&quot;">​</a></h2><p>Returned on list/show and accepted on create/update:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>exclude_from_lead_auto_assign</code></td><td>boolean</td><td><code>false</code></td><td>When <code>true</code>, user is omitted from lead assignee pickers and equal-distribution import/bulk. Workspace owners are typically <code>true</code>.</td></tr><tr><td><code>receive_website_leads</code></td><td>boolean</td><td><code>false</code></td><td>When <code>true</code>, user may receive custom webhook leads when an endpoint has <code>assign_to_website_recipients</code> enabled. Must also pass <code>eligibleLeadAssignees</code>.</td></tr><tr><td><code>receive_all_users_daily_summary</code></td><td>boolean</td><td><code>false</code></td><td>When <code>true</code>, at <strong>Daily Reminder Time</strong> the user receives the <strong>team</strong> (user-wise) CRM summary email and <strong>not</strong> a personal summary. Grants visibility into other members’ open leads/tasks/meetings counts. Prefer Owner/Admin.</td></tr><tr><td><code>lead_commission_rate</code></td><td>number | null</td><td><code>null</code></td><td>Optional default commission percentage (0–100). Snapshotted onto <code>leads.commission_rate</code> when this user is assigned via the assign endpoint. Reporting/display only — not used for payouts.</td></tr></tbody></table><p>Example create payload fragment:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Sales Manager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manager@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Password1!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exclude_from_lead_auto_assign&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;receive_all_users_daily_summary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;lead_commission_rate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12.5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>These columns are not mass-assignable on the <code>User</code> model; <code>TenantUserService</code> applies them via <code>forceFill</code> after validation.</p><h2 id="user-impersonation-login-as-user" tabindex="-1">User impersonation (login as user) <a class="header-anchor" href="#user-impersonation-login-as-user" aria-label="Permalink to &quot;User impersonation (login as user)&quot;">​</a></h2><p>Same-workspace support handoff. Not a marketplace module; gated by Spatie permission only.</p><h3 id="post-users-user-impersonate" tabindex="-1"><code>POST /users/{user}/impersonate</code> <a class="header-anchor" href="#post-users-user-impersonate" aria-label="Permalink to &quot;\`POST /users/{user}/impersonate\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Middleware</th><th>Value</th></tr></thead><tbody><tr><td>Permission</td><td><code>can:users.impersonate</code></td></tr><tr><td>Policy</td><td><code>TenantUserPolicy::impersonate</code> — denies self and workspace Owner (<code>superadmin</code>)</td></tr></tbody></table><p>Body:</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>reason</code></td><td>required, string, 5–1000 chars</td></tr></tbody></table><p>Behavior:</p><ul><li>Mints a Sanctum token named <code>user-impersonation</code> for the target (TTL 1 hour)</li><li>Creates a <code>user_impersonation_sessions</code> row (actor, target, reason, IP, user agent, PAT id)</li><li>Audits <code>user_impersonation_started</code></li><li>Rejects nested impersonation when the current bearer token is named <code>impersonation</code> (Central) or <code>user-impersonation</code></li><li>Rejects suspended targets (<code>422</code> on <code>user</code>)</li></ul><p>Response <code>201</code> includes session fields plus <code>target_token</code> and <code>expires_at</code>.</p><h3 id="post-user-impersonation-userimpersonation-end" tabindex="-1"><code>POST /user-impersonation/{userImpersonation}/end</code> <a class="header-anchor" href="#post-user-impersonation-userimpersonation-end" aria-label="Permalink to &quot;\`POST /user-impersonation/{userImpersonation}/end\`&quot;">​</a></h3><p>Authorizes when the current Sanctum PAT matches the session’s <code>personal_access_token_id</code>, or the actor still holds <code>users.impersonate</code> and owns the session. Ends the session, revokes the target PAT, audits <code>user_impersonation_ended</code>.</p><p>Central platform impersonation (<code>POST /api/central/v1/tenants/{tenant}/impersonate</code>) remains a separate product surface.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/tenant-v1-employees">Tenant Employees API</a></li><li><a href="/api/tenant-v1-notifications#scheduled-due-digests">Tenant notifications — daily CRM summary</a></li><li><a href="/deployment/daily-crm-summary">Daily CRM summary production</a></li><li><a href="/user-guide/tenant-rbac">Tenant RBAC user guide</a></li><li><a href="/developer-guide/authentication#impersonation-compatibility">Authentication (developer)</a></li></ul>`,32)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
